const input = $('Get Applicant').first().json || {};
const SCHEDULE_BASE = "https://unappropriated-tatyana-nonpedagogically.ngrok-free.dev/webhook/schedule";

const clean = (raw) => {
  const o = {};
  for (const [k, v] of Object.entries(raw || {})) o[String(k).trim()] = v;
  return o;
};
const app = clean($('Get Applicant').first().json);
const job = clean($('Get Job').first().json);
const rec = clean($('Get Recruiter').first().json);

const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fail = (reason) => [{ json: { send: false, reason, applicationId: input.applicationId } }];

if (!app.applicationId || String(app.applicationId).trim() !== String(input.applicationId || "").trim()) return fail("Applicant not found.");
if (String(app.bookingInviteSentAt || "").trim()) return fail("Booking invite already sent.");
if (String(app.interviewDate || "").trim()) return fail("An interview is already booked.");
if (!job.jobId) return fail("Job not found.");
if (!rec.recruiterName) return fail("No recruiter is linked to this job.");

const name = String(app.applicantName || "").trim();
const first = esc(name.split(" ")[0] || "there");
const role = esc(app.appliedPosition || job.role || "the position");

// A random token that only this applicant's invite contains
const chars = "abcdefghjkmnpqrstuvwxyz23456789";
let scheduleToken = "";
for (let i = 0; i < 24; i++) scheduleToken += chars[Math.floor(Math.random() * chars.length)];

const query = [
  ["applicationId", String(app.applicationId).trim()],
  ["token", scheduleToken]
].map(([k, v]) => encodeURIComponent(k) + "=" + encodeURIComponent(v)).join("&");
const bookingUrl = SCHEDULE_BASE + "?" + query;

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;background-color:#f1f5f9;margin:0;padding:30px 15px;">
  <div style="max-width:560px;margin:0 auto;background-color:#ffffff;border-radius:12px;border:1px solid #e2e8f0;overflow:hidden;">
    <div style="background-color:#075e4b;color:#ffffff;padding:26px 24px;text-align:center;">
      <div style="font-size:32px;line-height:1;">🎉</div>
      <h2 style="margin:10px 0 0 0;font-size:21px;font-weight:700;">Great news, ${first}!</h2>
      <p style="margin:6px 0 0 0;font-size:14px;opacity:0.9;">You passed our initial screening</p>
    </div>
    <div style="padding:28px 24px;color:#1e293b;font-size:15px;line-height:1.6;">
      <p style="margin:0 0 14px 0;">Hi ${first},</p>
      <p style="margin:0 0 14px 0;">Thank you for applying for the <strong>${role}</strong> position. Your profile stood out to us, and we would like to meet you.</p>
      <p style="margin:0 0 20px 0;">Please choose a time that suits you for a short interview:</p>
      <div style="text-align:center;margin:0 0 22px 0;">
        <a href="${esc(bookingUrl)}" style="background-color:#075e4b;color:#ffffff;text-decoration:none;padding:13px 26px;border-radius:8px;font-weight:700;font-size:15px;display:inline-block;">Choose your interview time</a>
      </div>
      <p style="margin:0 0 14px 0;font-size:13px;color:#64748b;">If the button doesn't work, copy this link into your browser:<br>${esc(bookingUrl)}</p>
      <p style="margin:20px 0 0 0;">Warm regards,<br><strong>The Hiring Team</strong></p>
    </div>
    <div style="background-color:#f8fafc;border-top:1px solid #e2e8f0;padding:14px 24px;text-align:center;color:#94a3b8;font-size:11px;">
      Reference ID: ${esc(app.applicationId)}
    </div>
  </div>
</body></html>`;

return [{ json: {
  send: true,
  reason: "",
  applicationId: String(app.applicationId).trim(),
  scheduleToken,
  to: String(app.applicantEmail || "").trim(),
  replyTo: String(rec.recruiterEmail || "").trim(),
  subject: "Great news, " + (name.split(" ")[0] || "there") + ": choose your interview time",
  html
} }];
